    const fields = [
      {
        input: document.getElementById("full-name"),
        error: document.getElementById("full-name-error"),
        validate(value) {
          return value.trim() ? "" : "Please enter your full name.";
        }
      },
      {
        input: document.getElementById("email-address"),
        error: document.getElementById("email-address-error"),
        validate(value) {
          if (!value.trim()) {
            return "Please enter your email address.";
          }

          return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
            ? ""
            : "Please enter a valid email address.";
        }
      },
      {
        input: document.getElementById("phone-number"),
        error: document.getElementById("phone-number-error"),
        validate(value) {
          if (!value.trim()) {
            return "";
          }

          return /^\+?[0-9()\-\s]{7,20}$/.test(value.trim())
            ? ""
            : "Please use a valid phone format, such as +1 (555) 123-4567.";
        }
      }
    ];

    function setFieldState(field, showError) {
      const message = field.validate(field.input.value);
      const container = field.input.closest(".form-field");
      const shouldShow = showError && Boolean(message);

      container.classList.toggle("has-error", shouldShow);
      field.error.textContent = shouldShow ? message : "";
      field.input.setAttribute("aria-invalid", shouldShow ? "true" : "false");
    }

    fields.forEach((field) => {
      field.input.addEventListener("blur", () => {
        field.input.dataset.touched = "true";
        setFieldState(field, true);
      });

      field.input.addEventListener("input", () => {
        if (field.input.dataset.touched === "true") {
          setFieldState(field, true);
        }
      });
    });

    form.addEventListener("submit", (event) => {
      let hasErrors = false;

      fields.forEach((field) => {
        field.input.dataset.touched = "true";
        setFieldState(field, true);

        if (field.validate(field.input.value)) {
          hasErrors = true;
        }
      });

      if (hasErrors) {
        event.preventDefault();
      }
    });
  </script>
